package com.hbm.satellite.link;
import com.hbm.satellite.*;import com.hbm.api.computer.*;import com.hbm.multiblock.*;import api.hbm.redstoneoverradio.*;import com.hbm.world.structure.templates.radio.RTTYSystem;import net.minecraft.core.*;import net.minecraft.nbt.*;import net.minecraft.network.chat.Component;import net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.entity.BlockEntity;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.level.levelgen.Heightmap;
/** Real source satellite antenna: no slots, HE, fluid or GUI; actual6computer calls and original ROR commands. */
public final class SatelliteLinkBlockEntity extends BlockEntity implements ComputerControl,IRORValueProvider,IRORInteractive,MuffledMachine {
 public boolean connected;public int freq;public float rot=INACTIVE_ROT,prevRot=INACTIVE_ROT,lift=INACTIVE_LIFT,prevLift=INACTIVE_LIFT;public static final float SPEED=.25F,ACTIVE_ROT=-15F,ACTIVE_LIFT=-45F,INACTIVE_ROT=0F,INACTIVE_LIFT=-85F;public Component[] info=new Component[0];private boolean muffled,tilted;
 public SatelliteLinkBlockEntity(BlockPos pos,BlockState state){super(SatelliteLinkContent.ENTITY.get(),pos,state);}@Override public boolean isValidBlockState(BlockState state){return super.isValidBlockState(state)&&DummyableBlock.isCore(state);}
 public static void tick(Level world,BlockPos pos,BlockState state,SatelliteLinkBlockEntity link){if(world instanceof ServerLevel server){link.connected=false;if(sourceHeight(server,pos.getX(),pos.getZ())<=pos.getY())link.connected=SatelliteSavedData.getData(server).getSatFromFreq(link.freq)!=null;link.updateInfo(link.connected);var packet=link.getUpdatePacket();for(var player:server.players())if(player.distanceToSqr(pos.getX(),pos.getY(),pos.getZ())<150*150)player.connection.send(packet);}else{link.prevRot=link.rot;link.prevLift=link.lift;float r=link.connected?ACTIVE_ROT:INACTIVE_ROT,l=link.connected?ACTIVE_LIFT:INACTIVE_LIFT;if(Math.abs(link.rot-r)<=SPEED)link.rot=r;else if(link.rot<r)link.rot+=SPEED;else if(link.rot>r)link.rot-=SPEED;if(Math.abs(link.lift-l)<=SPEED)link.lift=l;else if(link.lift<l)link.lift+=SPEED;else if(link.lift>l)link.lift-=SPEED;}}
 /**1.7heightMap used opacity>0; modern MOTION_BLOCKING incorrectly counts the antenna's own nonopaque collision cells. */
 public static int sourceHeight(ServerLevel world,int x,int z){var p=new BlockPos.MutableBlockPos(x,world.getHeight(Heightmap.Types.WORLD_SURFACE,x,z)-1,z);for(int y=p.getY();y>=world.getMinBuildHeight();y--){p.setY(y);var state=world.getBlockState(p);if(state.getLightBlock(world,p)>0)return y+1;}return world.getMinBuildHeight();}
 private void updateInfo(boolean canConnect){if(!canConnect){if(info.length>0)info=new Component[0];return;}var sat=SatelliteSavedData.getData((ServerLevel)level).getSatFromFreq(freq);if(sat!=null)info=sat.getInfo((ServerLevel)level);}
 @Override public String[] getFunctionInfo(){return new String[]{PREFIX_VALUE+"connected",PREFIX_VALUE+"freq",PREFIX_VALUE+"rx",PREFIX_VALUE+"type",PREFIX_FUNCTION+"setfreq"+NAME_SEPARATOR+"freq",PREFIX_FUNCTION+"tx"+NAME_SEPARATOR+"payload",PREFIX_FUNCTION+"txrx"+NAME_SEPARATOR+"return freq"+PARAM_SEPARATOR+"payload"};}
 @Override public String provideRORValue(String name){if(name.equals(PREFIX_VALUE+"connected"))return connected?"TRUE":"FALSE";if(name.equals(PREFIX_VALUE+"freq"))return ""+freq;if(!(level instanceof ServerLevel server))return name.equals(PREFIX_VALUE+"type")||name.equals(PREFIX_VALUE+"rx")?"":null;var sat=SatelliteSavedData.getData(server).getSatFromFreq(freq);if(name.equals(PREFIX_VALUE+"type"))return sat==null?"":sat.getType();if(name.equals(PREFIX_VALUE+"rx"))return sat==null?"":sat.tx;return null;}
 @Override public String runRORFunction(String name,String[] params){if(!(level instanceof ServerLevel server))return null;if(name.equals(PREFIX_FUNCTION+"setfreq")&&params.length==1){freq=IRORInteractive.parseInt(params[0],0,100_000);setChanged();}if(name.equals(PREFIX_FUNCTION+"tx")&&params.length>0){var data=SatelliteSavedData.getData(server);var sat=data.getSatFromFreq(freq);String[] cmd=String.join(IRORInteractive.PARAM_SEPARATOR,params).split(" ");if(sat!=null){sat.onCommand(server,cmd);data.setDirty();}SatelliteRayEvents.reportEvent(server,worldPosition.getX(),worldPosition.getY(),worldPosition.getZ(),SatelliteRayEvents.RayEvent.INFO_RADIO,300);setChanged();}if(name.equals(PREFIX_FUNCTION+"txrx")&&params.length>1){var data=SatelliteSavedData.getData(server);var sat=data.getSatFromFreq(freq);String[] args=new String[params.length-1];System.arraycopy(params,1,args,0,args.length);String[] cmd=String.join(IRORInteractive.PARAM_SEPARATOR,args).split(" ");if(sat!=null){sat.onCommand(server,cmd);RTTYSystem.broadcast(server,params[0],sat.tx);data.setDirty();}SatelliteRayEvents.reportEvent(server,worldPosition.getX(),worldPosition.getY(),worldPosition.getZ(),SatelliteRayEvents.RayEvent.INFO_RADIO,300);setChanged();}return null;}
 @Override public String computerType(){return "ntm_satlink";}@Override public String[] computerMethods(){return new String[]{"isConnected","setFreq","getFreq","getType","send","read"};}@Override public Object[] callComputer(String method,ComputerArguments args){return switch(method){case "isConnected"->new Object[]{connected};case "setFreq"->{freq=args.checkInteger(0);setChanged();yield new Object[]{};}case "getFreq"->new Object[]{freq};case "getType"->new Object[]{provideRORValue(PREFIX_VALUE+"type")};case "send"->{runRORFunction(PREFIX_FUNCTION+"tx",new String[]{args.checkString(0)});yield new Object[]{};}case "read"->new Object[]{provideRORValue(PREFIX_VALUE+"rx")};default->throw new ComputerException("No such method");};}
 @Override public boolean isMuffled(){return muffled;}@Override public void setMuffled(boolean value){muffled=value;setChanged();}
 @Override protected void saveAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.saveAdditional(tag,lookup);tag.putInt("freq",freq);tag.putBoolean("muffled",muffled);tag.putBoolean("tilted",tilted);}@Override protected void loadAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.loadAdditional(tag,lookup);freq=tag.getInt("freq");muffled=tag.getBoolean("muffled");tilted=tag.getBoolean("tilted");}
 @Override public CompoundTag getUpdateTag(HolderLookup.Provider lookup){var tag=new CompoundTag();tag.putBoolean("muffled",muffled);tag.putBoolean("connected",connected);tag.putInt("freq",freq);var list=new ListTag();for(var component:info)list.add(StringTag.valueOf(component==null?"null":Component.Serializer.toJson(component,lookup)));tag.put("info",list);return tag;}
 @Override public void handleUpdateTag(CompoundTag tag,HolderLookup.Provider lookup){muffled=tag.getBoolean("muffled");connected=tag.getBoolean("connected");freq=tag.getInt("freq");var list=tag.getList("info",Tag.TAG_STRING);info=new Component[list.size()];for(int i=0;i<info.length;i++)info[i]=list.getString(i).equals("null")?null:Component.Serializer.fromJson(list.getString(i),lookup);}
 @Override public ClientboundBlockEntityDataPacket getUpdatePacket(){return ClientboundBlockEntityDataPacket.create(this);}@Override public void onDataPacket(net.minecraft.network.Connection connection,ClientboundBlockEntityDataPacket packet,HolderLookup.Provider lookup){handleUpdateTag(packet.getTag(),lookup);}
}
